      "newText": "using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;

namespace AiBox.DevPortal.Services;

public class ModelBenchmarkResultService
{
    public List<BenchmarkResultSummary> LoadResults()
    {
        var results = new List<BenchmarkResultSummary>();
        var directoryPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "tools", "model-benchmark", "results");

        foreach (var file in Directory.GetFiles(directoryPath, "*.json"))
        {
            var result = JsonConvert.DeserializeObject<BenchmarkResult>(File.ReadAllText(file));
            results.Add(new BenchmarkResultSummary
            {
                Name = result.Name,
                AverageTime = result.AverageTime,
                MinTime = result.MinTime,
                MaxTime = result.MaxTime
            });
        }

        return results;
    }
}

public class BenchmarkResult
{
    public string Name { get; set; }
    public double AverageTime { get; set; }
    public double MinTime { get; set; }
    public double MaxTime { get; set; }
}

public class BenchmarkResultSummary
{
    public string Name { get; set; }
    public double AverageTime { get; set; }
    public double MinTime { get; set; }
